    document.querySelector('#product-category-list').addEventListener('click', (event) => { const button = event.target.closest('.product-category-edit'); if (!button) return; const item = productCategoryItems.find((entry) => entry.id === button.dataset.category); if (!item) return; categoryForm.hidden = false; document.querySelector('#product-category-id').value = item.id; document.querySelector('#product-category-name').value = item.name; document.querySelector('#delete-product-category').hidden = false; });
