    const productPlaceholder = (item) => { const name = String(item.name || 'Позиция'); const category = String(item.category || item.station || 'Каталог'); const initials = name.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]).join('').toLocaleUpperCase('ru-RU'); const palette = [...name].reduce((sum, char) => sum + char.charCodeAt(0), 0) % 5 + 1; return `<div class="visual-product-placeholder palette-${palette}" aria-label="Превью ${esc(name)}"><strong>${esc(initials || '•')}</strong><span>${esc(category)}</span></div>`; }; let productItems = []; const normalizeInventorySearch = (value) => String(value || '').toLocaleLowerCase('ru-RU').replace(/ё/g, 'е').replace(/[^\p{L}\p{N}]+/gu, ' ').trim(); const drawProducts = (items = productItems) => { productItems = items; const grid = document.querySelector('#visual-catalog'); const query = normalizeInventorySearch(document.querySelector('#product-search')?.value); const visible = items.filter((item) => normalizeInventorySearch([item.name, ...(item.aliases || [])].join(' ')).includes(query)); grid.innerHTML = visible.length ? visible.map((item) => `<article class="visual-product" data-product-id="${esc(item.id)}"><div class="visual-product-image">${item.imageUrl ? `<img src="${item.imageUrl}" alt="${esc(displayName(item.name))}">` : productPlaceholder(item)}</div><b>${esc(displayName(item.name))}</b><small>${money(item.price)} · ${esc(item.category || item.station || 'Без категории')}</small><div class="product-card-actions">${canWriteInventory ? `<button class="button small product-edit" type="button" data-product="${esc(item.id)}">Изменить</button>` : ''}<label class="upload-button">${item.imageUrl ? 'Заменить фото' : 'Загрузить фото'}<input type="file" accept="image/png,image/jpeg,image/webp" data-product="${item.id}" hidden></label></div></article>`).join('') : '<div class="empty">Товаров по запросу нет</div>'; grid.querySelectorAll('input[type=file]').forEach((input) => input.addEventListener('change', () => { const file = input.files[0]; if (!file) return; if (!['image/png','image/jpeg','image/webp'].includes(file.type) || file.size > 1_500_000) { portalNotice('Фото товара: PNG, JPG или WebP до 1.5 МБ', 'error'); input.value = ''; return; } const card = input.closest('.visual-product'); const reader = new FileReader(); reader.onload = () => { const preview = card?.querySelector('img') || card?.querySelector('.visual-product-image'); if (preview) preview.src ? preview.src = reader.result : preview.innerHTML = `<img src="${reader.result}" alt="Предпросмотр">`; input.disabled = true; api(`/api/products/${input.dataset.product}/image`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ imageData: reader.result }) }).then(() => api('/api/products')).then((data) => { drawProducts(data.items); portalNotice('Фото товара сохранено', 'success'); }).catch(() => { input.disabled = false; portalNotice('Не удалось сохранить фото товара', 'error'); }); }; reader.onerror = () => { input.disabled = false; portalNotice('Не удалось прочитать фото товара', 'error'); }; reader.readAsDataURL(file); })); grid.querySelectorAll('.product-edit').forEach((button) => button.addEventListener('click', () => { const item = productItems.find((entry) => entry.id === button.dataset.product); if (!item) return; const form = document.querySelector('#product-form'); form.hidden = false; document.querySelector('#product-id').value = item.id; document.querySelector('#product-name').value = item.name; document.querySelector('#product-category').value = item.category || item.station || ''; document.querySelector('#product-price').value = item.price; document.querySelector('#product-aliases').value = (item.aliases || []).join(', '); document.querySelector('#delete-product').hidden = false; form.scrollIntoView({ behavior: 'smooth', block: 'center' }); })); };
  api('/api/products').then((data) => drawProducts(data.items)).catch(() => { document.querySelector('#visual-catalog').innerHTML = '<div class="empty">Не удалось загрузить каталог</div>'; portalNotice('Не удалось загрузить каталог', 'error'); }); document.querySelector('#product-search')?.addEventListener('input', () => drawProducts());
  const recipes = document.createElement('section'); recipes.className = 'panel recipes-panel'; recipes.innerHTML = '<div class="panel-head"><div><h2>Технологические карты</h2><span class="muted">Рецептуры чая из импортированных Excel-ТТК</span></div><span class="badge" id="recipe-count">Загрузка…</span></div><div id="recipe-grid" class="recipe-grid"><div class="empty">Загрузка рецептур…</div></div>'; target.append(recipes);
  api('/api/recipes').then((data) => { const items = data.items || []; const count = document.querySelector('#recipe-count'); if (count) count.textContent = `${items.length} карт`; const grid = document.querySelector('#recipe-grid'); if (!grid) return; grid.innerHTML = items.length ? items.map((recipe) => `<article class="recipe-card"><div class="recipe-card-head"><h3>${esc(displayName(recipe.name))}</h3><span>${recipe.ingredients?.length || 0} инг.</span></div><ul>${(recipe.ingredients || []).map((ingredient) => `<li><span>${esc(ingredient.name)}</span><b>${esc(ingredient.quantity || '—')}</b></li>`).join('')}</ul>${recipe.technology ? `<p><strong>Технология:</strong> ${esc(recipe.technology)}</p>` : ''}${recipe.serve ? `<p><strong>Подача:</strong> ${esc(recipe.serve)}</p>` : ''}</article>`).join('') : '<div class="empty">Рецептуры не найдены</div>'; }).catch(() => { const grid = document.querySelector('#recipe-grid'); if (grid) grid.innerHTML = '<div class="empty">Не удалось загрузить рецептуры</div>'; });
  if (canWriteInventory) { const form = document.querySelector('#product-form'); const resetProductForm = () => { form.reset(); document.querySelector('#product-id').value = ''; document.querySelector('#delete-product').hidden = true; form.hidden = true; }; document.querySelector('#new-product').addEventListener('click', () => { resetProductForm(); form.hidden = false; form.scrollIntoView({ behavior: 'smooth', block: 'center' }); document.querySelector('#product-name').focus(); }); document.querySelector('#cancel-product').addEventListener('click', resetProductForm); form.addEventListener('submit', (event) => { event.preventDefault(); const id = document.querySelector('#product-id').value; const payload = { name: document.querySelector('#product-name').value.trim(), category: document.querySelector('#product-category').value.trim(), price: Number(document.querySelector('#product-price').value), aliases: document.querySelector('#product-aliases').value.split(',').map((item) => item.trim()).filter(Boolean) }; const message = document.querySelector('#product-message'); api(id ? `/api/products/${encodeURIComponent(id)}` : '/api/products', { method: id ? 'PATCH' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }).then(() => api('/api/products')).then((data) => { drawProducts(data.items); message.textContent = 'Товар сохранён'; message.className = 'form-message success-message'; resetProductForm(); }).catch(() => { message.textContent = 'Не удалось сохранить товар'; message.className = 'form-message error-message'; }); }); document.querySelector('#delete-product').addEventListener('click', () => { const id = document.querySelector('#product-id').value; if (!id) return; const button = document.querySelector('#delete-product'); button.disabled = true; api(`/api/products/${encodeURIComponent(id)}`, { method: 'DELETE' }).then(() => api('/api/products')).then((data) => { drawProducts(data.items); resetProductForm(); portalNotice('Товар скрыт из каталога', 'success'); }).catch(() => portalNotice('Не удалось удалить товар', 'error')).finally(() => { button.disabled = false; }); }); }
