  document.querySelector('#movement-form')?.addEventListener('submit', (event) => { event.preventDefault(); const form = event.target; if (form.dataset.submitting === '1') return; form.dataset.submitting = '1'; const submit = form.querySelector('button[type="submit"]'); if (submit) submit.disabled = true; const message = document.querySelector('#movement-message'); api('/api/inventory/movements', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ itemId: document.querySelector('#movement-item').value, delta: (document.querySelector('#movement-direction').value === 'out' ? -1 : 1) * Number(document.querySelector('#movement-delta').value), reason: document.querySelector('#movement-reason').value }) }).then(() => { message.className = 'form-message success-message'; message.textContent = 'Движение сохранено'; form.reset(); load(); }).catch((error) => { const reason = String(error.payload?.error || error.message || ''); message.className = 'form-message error-message'; message.textContent = reason.includes('409') || reason === 'insufficient_stock' ? 'Недостаточно остатка для расхода' : reason === 'movement_reason_too_long' ? 'Причина не должна быть длиннее 200 символов' : 'Не удалось сохранить движение'; }).finally(() => { form.dataset.submitting = '0'; if (submit) submit.disabled = false; }); });
