function renderFinanceCategories() {
  const target = document.querySelector('#page-content'); if (!target) return;
  const canWrite = portalPermissions.has('finance');
  target.innerHTML = `<div class="page-title"><div><p class="eyebrow">ФИНАНСОВЫЙ СПРАВОЧНИК</p><h1>Категории финансов</h1><p class="muted">Разделяйте выручку и расходы по понятным направлениям.</p></div><div class="toolbar-row"><a class="button" href="/finance">${icon('arrow-left')} Финансы</a>${canWrite ? `<button class="button primary" id="new-finance-category" type="button">${icon('plus')} Категория</button>` : '<span class="badge">Только просмотр</span>'}</div></div><section class="panel wide"><div class="panel-head"><div><h2>Категории</h2><span class="muted" id="finance-category-count">Загрузка…</span></div><input class="table-search" id="finance-category-search" aria-label="Поиск категорий" placeholder="Поиск"></div>${canWrite ? '<form id="finance-category-form" class="product-editor" hidden><input type="hidden" id="finance-category-id"><label>Название<input id="finance-category-name" maxlength="80" required placeholder="Например, Бар"></label><label>Тип<select id="finance-category-kind"><option value="income">Доход</option><option value="expense">Расход</option></select></label><div class="toolbar-row"><button class="button primary" type="submit">Сохранить</button><button class="button" id="cancel-finance-category" type="button">Отмена</button><button class="button danger-outline" id="delete-finance-category" type="button" hidden>Скрыть</button></div><p class="form-message" id="finance-category-message"></p></form>' : ''}<div class="category-list" id="finance-category-list"><div class="empty">Загрузка категорий…</div></div></section><section class="panel rules-panel" id="control-rules"><div class="panel-head"><div><h2>Правила контроля</h2><span class="muted">Логика финансовых операций и согласований</span></div></div><div class="rule"><b>Скидка</b><span>Сотрудник указывает причину, администратор и управляющий получают уведомление.</span></div><div class="rule"><b>VIP</b><span>Сумма заказа VIP-комнаты не ниже обязательного минимума.</span></div><div class="rule"><b>Аудит</b><span>Оплата, возврат и корректировка сохраняются в журнале действий.</span></div></section>`;
  let items = [];
  const draw = () => { const q = document.querySelector('#finance-category-search').value.trim().toLocaleLowerCase('ru-RU'); const visible = items.filter((item) => !q || item.name.toLocaleLowerCase('ru-RU').includes(q)); document.querySelector('#finance-category-count').textContent = `${visible.length} из ${items.length} категорий`; document.querySelector('#finance-category-list').innerHTML = visible.length ? visible.map((item) => `<div class="category-row"><div><b>${esc(displayName(item.name))}</b><small>${item.kind === 'income' ? 'Доход' : 'Расход'}</small></div><span class="badge ${item.kind === 'income' ? 'success' : 'warning'}">${item.kind === 'income' ? 'Доход' : 'Расход'}</span>${canWrite ? `<button class="button small finance-category-edit" type="button" data-category="${esc(item.id)}">Изменить</button>` : ''}</div>`).join('') : '<div class="empty">Категории не найдены</div>'; };
  const load = () => api('/api/finance/categories').then((data) => { items = (data.items || []).filter((item) => item.active !== false); draw(); }).catch(() => portalNotice('Не удалось загрузить категории финансов', 'error'));
  document.querySelector('#finance-category-search').addEventListener('input', draw);
  if (canWrite) { const form = document.querySelector('#finance-category-form'); const reset = () => { form.reset(); document.querySelector('#finance-category-id').value = ''; document.querySelector('#delete-finance-category').hidden = true; form.hidden = true; }; document.querySelector('#new-finance-category').addEventListener('click', () => { reset(); form.hidden = false; form.scrollIntoView({ behavior: 'smooth', block: 'center' }); document.querySelector('#finance-category-name').focus(); }); document.querySelector('#cancel-finance-category').addEventListener('click', reset); document.querySelector('#finance-category-list').addEventListener('click', (event) => { const button = event.target.closest('[data-category]'); if (!button) return; const item = items.find((entry) => entry.id === button.dataset.category); if (!item) return; form.hidden = false; document.querySelector('#finance-category-id').value = item.id; document.querySelector('#finance-category-name').value = item.name; document.querySelector('#finance-category-kind').value = item.kind; document.querySelector('#delete-finance-category').hidden = false; form.scrollIntoView({ behavior: 'smooth', block: 'center' }); }); form.addEventListener('submit', (event) => { event.preventDefault(); const id = document.querySelector('#finance-category-id').value; const message = document.querySelector('#finance-category-message'); const payload = { name: document.querySelector('#finance-category-name').value.trim(), kind: document.querySelector('#finance-category-kind').value }; api(id ? `/api/finance/categories/${encodeURIComponent(id)}` : '/api/finance/categories', { method: id ? 'PATCH' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }).then(() => { message.textContent = 'Категория сохранена'; message.className = 'form-message success-message'; reset(); load(); }).catch(() => { message.textContent = 'Не удалось сохранить категорию'; message.className = 'form-message error-message'; }); }); document.querySelector('#delete-finance-category').addEventListener('click', () => { const id = document.querySelector('#finance-category-id').value; if (!id) return; api(`/api/finance/categories/${encodeURIComponent(id)}`, { method: 'DELETE' }).then(() => { reset(); load(); portalNotice('Категория скрыта', 'success'); }).catch(() => portalNotice('Не удалось скрыть категорию', 'error')); }); }
  load();
}

function renderFinance() {
  const target = document.querySelector('#page-content'); if (!target) return;
  const canDecideFinance = portalPermissions.has('finance');
  target.innerHTML = `<div class="page-title"><div><p class="eyebrow">КОНТРОЛЬ ДЕНЕГ</p><h1>Финансы</h1><p class="muted">Сводка оплат, выручки и заявок на скидку.</p></div><input class="date-input" type="date" value="${localDateKey()}" id="finance-date"></div><div class="kpi-grid compact"><article class="kpi" data-kpi-target="#payment-list" aria-label="Показать оплаты"><span>Выручка</span><strong id="finance-revenue">—</strong><small>С учётом депозитов VIP-комнат</small><small id="finance-pending-inline" class="pending-inline">В заказах не оплачено: —</small></article><article class="kpi" data-kpi-route="/" aria-label="Открыть рабочее место"><span>Заказы</span><strong id="finance-orders">—</strong><small id="finance-orders-detail">Закрытые и открытые</small></article><article class="kpi" data-kpi-target="#discount-list" aria-label="Показать заявки на скидку"><span>Заявки на скидку</span><strong id="finance-discounts">—</strong><small>Ожидают решения</small></article><article class="kpi" data-kpi-target="#payment-list" aria-label="Показать платежи"><span>Платежи</span><strong id="finance-payments">—</strong><small id="finance-average-check">Проведено операций · Средний чек смены: —</small></article><article class="kpi pending-revenue-kpi" data-kpi-route="/" aria-label="Открыть рабочее место с открытыми заказами"><span>Ожидают оплаты</span><strong id="finance-pending-revenue">—</strong><small id="finance-pending-detail">Открытые заказы без полной оплаты</small></article></div><section class="panel finance-chart-panel"><div class="panel-head"><div><h2>Динамика показателей</h2><span class="muted">Настраиваемая инфографика за выбранный период</span></div><div class="toolbar-row finance-chart-controls"><label>Показатель<select id="finance-chart-metric"><option value="revenue">Выручка</option><option value="orders">Заказы</option><option value="average">Средний чек</option></select></label><label>Период<select id="finance-chart-period"><option value="7">7 дней</option><option value="5">5 дней</option><option value="3">3 дня</option></select></label></div></div><div id="finance-chart" class="finance-chart"><div class="empty">Загрузка графика…</div></div></section><section class="panel cash-register-panel is-closed"><div class="panel-head"><div><h2>Смена и касса</h2><span class="muted" id="cash-register-status">Проверяем состояние смены…</span><small class="cash-register-hint" id="cash-register-hint">Смена связывает оплаты с текущим рабочим периодом.</small></div><a class="button small" id="cash-register-action" href="/admin#shift-control">Открыть смену</a></div><div class="cash-register-grid"><div><span>Стартовый остаток</span><strong id="cash-register-opening">—</strong></div><div><span>Открыта</span><strong id="cash-register-opened">—</strong></div><div><span>Номер смены</span><strong id="cash-register-id">—</strong></div></div></section><div class="content-grid"><section class="panel wide"><div class="panel-head"><h2>Оплаты по способу</h2></div><div class="payment-list" id="payment-list"></div></section></div><section class="panel discount-panel" id="discounts"><div class="panel-head"><div><h2>Заявки на скидку</h2><span class="muted">Применённые скидки и уведомления руководству</span></div></div><div id="discount-list" class="discount-list"><div class="empty">Загрузка заявок…</div></div></section>`;
  bindKpiNavigation();
  const drawDiscounts = (items) => { const list = document.querySelector('#discount-list'); const pending = items.filter((item) => item.status === 'requested'); list.innerHTML = items.length ? items.map((item) => `<div class="discount-row"><div><b>${item.type === 'percent' ? `${item.value}%` : money(item.value)} скидка</b><small>Заказ ${esc(item.orderId)}${item.guestName ? ` · гость: ${esc(item.guestName)}${item.guestPhone ? ` (${esc(item.guestPhone)})` : ''}` : ''} · ${esc(item.reason)} · запросил ${esc(item.requestedBy || 'сотрудник')}</small></div><span class="badge ${item.status === 'requested' ? 'warning' : item.status === 'approved' ? 'success' : 'danger'}">${item.status === 'requested' ? 'На согласовании' : item.status === 'approved' ? 'Применена' : 'Отклонена'}</span>${item.status === 'requested' ? (canDecideFinance ? `<div class="discount-actions"><button type="button" class="button small discount-approve" data-discount="${item.id}">Одобрить</button><button type="button" class="button small danger-outline discount-reject" data-discount="${item.id}">Отклонить</button></div>` : '<small class="muted">Требуется право финансового решения</small>') : ''}</div>`).join('') : '<div class="empty">Заявок на скидку нет</div>'; document.querySelector('#finance-discounts').textContent = pending.length; };
  const drawFinanceChart = (analytics) => {
    const chart = document.querySelector('#finance-chart'); if (!chart) return;
    const metric = document.querySelector('#finance-chart-metric')?.value || 'revenue';
    const period = Number(document.querySelector('#finance-chart-period')?.value || 7);
    const days = (analytics?.days || []).slice(-period);
    const values = days.map((day) => metric === 'orders' ? Number(day.orders || 0) : metric === 'average' ? (Number(day.orders || 0) ? Number(day.revenue || 0) / Number(day.orders || 0) : 0) : Number(day.revenue || 0));
    const max = Math.max(...values, 1);
    const total = values.reduce((sum, value) => sum + value, 0);
    const peakIndex = values.reduce((best, value, index) => value > (values[best] || 0) ? index : best, 0);
    const format = metric === 'orders' ? (value) => String(Math.round(value)) : (value) => money(Math.round(value));
    const summaryLabels = metric === 'orders' ? ['Заказов за период', 'Пик за день', 'Среднее в день'] : metric === 'average' ? ['Средний чек', 'Лучший чек', 'Средний показатель'] : ['Выручка за период', 'Лучший день', 'Среднее в день'];
    const summaryValues = metric === 'average' ? [format(values.length ? total / values.length : 0), format(values[peakIndex] || 0), format(values.length ? total / values.length : 0)] : [format(total), format(values[peakIndex] || 0), format(values.length ? total / values.length : 0)];
    chart.innerHTML = days.length ? `<div class="finance-chart-summary">${summaryLabels.map((label, index) => `<div><span>${label}</span><strong>${summaryValues[index]}</strong></div>`).join('')}</div><div class="finance-chart-grid"><i></i><i></i><i></i><i></i><div class="finance-chart-bars">${days.map((day, index) => `<div class="finance-chart-column" title="${day.date}: ${format(values[index])}"><strong>${format(values[index])}</strong><span class="finance-chart-bar" style="height:${Math.max(5, Math.round(values[index] / max * 100))}%"></span><small>${String(day.date || '').slice(5).replace('-', '.')}</small></div>`).join('')}</div></div>` : '<div class="empty">Нет данных за период</div>';
  };
  const load = () => Promise.all([api(`/api/finance/summary?date=${document.querySelector('#finance-date').value}`), api('/api/discount-requests'), api('/api/shifts'), api('/api/analytics')]).then(([summary, discounts, shifts, analytics]) => { document.querySelector('#finance-revenue').textContent = money(summary.revenue); const pendingInline = document.querySelector('#finance-pending-inline'); if (pendingInline) pendingInline.textContent = `В заказах не оплачено: ${money(summary.pendingRevenue || 0)}`; const totalOrders = Number(summary.closedOrders || 0) + Number(summary.pendingOrders || 0); document.querySelector('#finance-orders').textContent = totalOrders; const ordersDetail = document.querySelector('#finance-orders-detail'); if (ordersDetail) ordersDetail.textContent = `Закрытые: ${summary.closedOrders || 0} · открытые: ${summary.pendingOrders || 0}`; const pendingAmount = document.querySelector('#finance-pending-revenue'); if (pendingAmount) pendingAmount.textContent = money(summary.pendingRevenue); const pendingDetail = document.querySelector('#finance-pending-detail'); if (pendingDetail) pendingDetail.textContent = `${summary.pendingOrders || 0} ${pluralRu(summary.pendingOrders || 0, 'заказ', 'заказа', 'заказов')} без полной оплаты`; const paymentCount = document.querySelector('#finance-payments'); if (paymentCount) paymentCount.textContent = summary.paymentCount ?? '—'; const averageCheck = document.querySelector('#finance-average-check'); if (averageCheck) averageCheck.textContent = `Средний чек смены: ${summary.currentShiftOrders ? money(summary.currentShiftAverageCheck) : '—'}${summary.currentShiftOrders ? ` · ${summary.currentShiftOrders} ${pluralRu(summary.currentShiftOrders, 'чек', 'чека', 'чеков')}` : ' · пока нет закрытых чеков'}`; const paymentLabels = { cash: 'Наличные', card: 'Карта', qr: 'QR', 'не указан': 'Не указан' }; const rows = Object.entries(summary.byPaymentMethod); document.querySelector('#payment-list').innerHTML = rows.length ? rows.map(([method, value]) => `<div class="payment-row"><span>${esc(paymentLabels[method] || method)}</span><strong>${money(value)}</strong></div>`).join('') : '<div class="empty">Оплат за выбранную дату пока нет</div>'; const shift = shifts.current; const cashPanel = document.querySelector('.cash-register-panel'); const cashStatus = document.querySelector('#cash-register-status'); const cashHint = document.querySelector('#cash-register-hint'); const cashAction = document.querySelector('#cash-register-action'); if (cashPanel) cashPanel.classList.toggle('is-open', Boolean(shift)); if (cashPanel) cashPanel.classList.toggle('is-closed', !shift); if (cashStatus) cashStatus.textContent = shift ? 'Смена открыта · оплаты привязаны к текущему периоду' : 'Смена не открыта · перед началом работы её нужно открыть'; if (cashHint) cashHint.textContent = shift ? 'Проверьте выручку и закройте смену через X‑отчёт.' : 'Открытие фиксирует стартовый остаток и связывает все оплаты со сменой.'; if (cashAction) { cashAction.textContent = shift ? 'Открыть X‑отчёт' : 'Открыть смену'; cashAction.href = shift ? '/finance/report' : '/admin#shift-control'; } document.querySelector('#cash-register-opening').textContent = shift ? money(shift.openingCash || 0) : 'Не задан'; document.querySelector('#cash-register-opened').textContent = shift ? new Date(shift.openedAt).toLocaleString('ru-RU', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : 'Не открыта'; document.querySelector('#cash-register-id').textContent = shift?.id || 'После открытия'; drawDiscounts(discounts.items || []); window.__financeAnalytics = analytics; drawFinanceChart(analytics); }).catch(() => { document.querySelector('#finance-revenue').textContent = 'Ошибка'; document.querySelector('#payment-list').innerHTML = '<div class="empty">Не удалось загрузить финансовую сводку</div>'; portalNotice('Не удалось загрузить финансы', 'error'); });
  document.querySelector('#discount-list')?.addEventListener('click', (event) => { const button = event.target.closest('[data-discount]'); if (!button || button.disabled) return; const action = button.classList.contains('discount-approve') ? 'approve' : 'reject'; const sibling = button.parentElement?.querySelector(`[data-discount="${button.dataset.discount}"]:not([disabled])`); button.disabled = true; if (sibling) sibling.disabled = true; api(`/api/discount-requests/${button.dataset.discount}/${action}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' }).then(() => { portalNotice(action === 'approve' ? 'Скидка одобрена' : 'Скидка отклонена', 'success'); load(); }).catch(() => { button.disabled = false; if (sibling) sibling.disabled = false; portalNotice('Не удалось обработать скидку', 'error'); }); });
  document.querySelector('#finance-date').addEventListener('change', load); document.querySelector('#finance-chart-metric')?.addEventListener('change', () => drawFinanceChart(window.__financeAnalytics || {})); document.querySelector('#finance-chart-period')?.addEventListener('change', () => drawFinanceChart(window.__financeAnalytics || {})); load();
}

function renderDelivery() {
  const target = document.querySelector('#page-content'); if (!target) return;
  target.innerHTML = `<div class="page-title"><div><p class="eyebrow">ДОСТАВКА</p><h1>Заказы доставки</h1><p class="muted">Адреса, контакты, оплата и текущий статус курьера.</p></div><span class="live-dot">● Локальный контур</span></div><div class="content-grid"><section class="panel"><div class="panel-head"><h2>Новая доставка</h2></div><form class="stack-form" id="delivery-form"><label>Имя гостя<input id="delivery-name" required maxlength="120" placeholder="Имя и фамилия"></label><label>Телефон<input id="delivery-phone" placeholder="+7 ..."></label><label>Адрес<textarea id="delivery-address" required maxlength="500" rows="2" placeholder="Улица, дом, квартира"></textarea></label><label>Сумма<input id="delivery-total" type="number" min="0" step="1" value="0"></label><label>Оплата<select id="delivery-payment"><option value="cash">Наличные</option><option value="card">Карта</option><option value="qr">QR</option></select></label><label>Комментарий<textarea id="delivery-comment" maxlength="500" rows="2" placeholder="Домофон, пожелания…"></textarea></label><button class="button primary" type="submit">Создать доставку</button><p class="form-message" id="delivery-message"></p></form></section><section class="panel wide"><div class="panel-head"><div><h2>Очередь доставки</h2><span class="muted" id="delivery-count">Загрузка…</span></div><select id="delivery-filter" aria-label="Статус доставки"><option value="">Все статусы</option><option value="new">Новая</option><option value="confirmed">Подтверждена</option><option value="in_delivery">У курьера</option><option value="delivered">Доставлена</option><option value="cancelled">Отменена</option></select></div><div class="delivery-list" id="delivery-list"><div class="empty">Загрузка доставок…</div></div></section></div>`;
  let items = []; const labels = { new: 'Новая', confirmed: 'Подтверждена', in_delivery: 'У курьера', delivered: 'Доставлена', cancelled: 'Отменена' };
  const draw = () => { const filter = document.querySelector('#delivery-filter').value; const list = document.querySelector('#delivery-list'); const filtered = items.filter((item) => !filter || item.status === filter); document.querySelector('#delivery-count').textContent = `${filtered.length} ${pluralRu(filtered.length,'заказ','заказа','заказов')}`; list.innerHTML = filtered.length ? filtered.map((item) => `<article class="delivery-row"><div><b>${esc(item.customerName)}</b><small>${esc(item.phone || 'Телефон не указан')} · ${esc(item.address)}</small><small>${item.comment ? esc(item.comment) : 'Без комментария'} · ${money(item.total)}</small></div><div class="delivery-actions"><span class="badge ${item.status === 'delivered' ? 'success' : item.status === 'cancelled' ? 'danger' : 'warning'}">${labels[item.status] || item.status}</span><select data-delivery-status="${esc(item.id)}" aria-label="Статус доставки"><option value="new" ${item.status === 'new' ? 'selected' : ''}>Новая</option><option value="confirmed" ${item.status === 'confirmed' ? 'selected' : ''}>Подтверждена</option><option value="in_delivery" ${item.status === 'in_delivery' ? 'selected' : ''}>У курьера</option><option value="delivered" ${item.status === 'delivered' ? 'selected' : ''}>Доставлена</option><option value="cancelled" ${item.status === 'cancelled' ? 'selected' : ''}>Отменена</option></select></div></article>`).join('') : '<div class="empty">Доставок по выбранному фильтру нет</div>'; };
  const load = () => api('/api/deliveries').then((data) => { items = data.items || []; draw(); }).catch(() => portalNotice('Не удалось загрузить доставки', 'error'));
  document.querySelector('#delivery-filter').addEventListener('change', draw); document.querySelector('#delivery-list').addEventListener('change', (event) => { const select = event.target.closest('[data-delivery-status]'); if (!select) return; api(`/api/deliveries/${encodeURIComponent(select.dataset.deliveryStatus)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: select.value }) }).then(load).catch(() => portalNotice('Не удалось изменить статус доставки', 'error')); });
  document.querySelector('#delivery-form').addEventListener('submit', (event) => { event.preventDefault(); const message = document.querySelector('#delivery-message'); api('/api/deliveries', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ customerName: document.querySelector('#delivery-name').value.trim(), phone: document.querySelector('#delivery-phone').value.trim(), address: document.querySelector('#delivery-address').value.trim(), total: Number(document.querySelector('#delivery-total').value), paymentMethod: document.querySelector('#delivery-payment').value, comment: document.querySelector('#delivery-comment').value.trim() }) }).then(() => { message.textContent = 'Доставка создана'; message.className = 'form-message success-message'; event.target.reset(); load(); }).catch((error) => { message.textContent = error.payload?.error === 'invalid_guest_phone' ? 'Проверьте телефон' : 'Не удалось создать доставку'; message.className = 'form-message error-message'; }); }); load();
}

function renderFinanceReport() {
  const target = document.querySelector('#page-content'); if (!target) return;
  target.innerHTML = `<div class="page-title"><div><p class="eyebrow">КОНТРОЛЬ СМЕНЫ</p><h1>Отчёты</h1><p class="muted">X‑отчёт показывает закрытые чеки и оплаты, отчёт официанта — выручку по сотрудникам.</p></div><a class="button" href="/finance">${icon('arrow-left')} Финансы</a></div><section class="panel wide report-controls"><div class="toolbar-row"><label>Дата<input id="report-date" type="date" value="${localDateKey()}"></label><label>Тип отчёта<select id="report-type"><option value="x">X‑отчёт смены</option><option value="waiter">Отчёт официанта</option></select></label><button class="button primary" id="report-refresh" type="button">Сформировать</button></div></section><section class="kpi-grid compact" id="report-kpis"><article class="kpi"><span>Выручка</span><strong id="report-revenue">—</strong><small>По закрытым чекам</small></article><article class="kpi"><span>Чеков закрыто</span><strong id="report-checks">—</strong><small id="report-meta">—</small></article><article class="kpi"><span>Наличные</span><strong id="report-cash">—</strong><small>Способ оплаты</small></article><article class="kpi"><span>Карта + QR</span><strong id="report-digital">—</strong><small>Безналичная выручка</small></article></section><div class="content-grid report-grid"><section class="panel"><div class="panel-head"><div><h2>Оплаты</h2><span class="muted" id="report-number">Отчёт ещё не сформирован</span></div></div><div class="report-breakdown" id="report-payments"><div class="empty">Выберите дату и сформируйте отчёт</div></div></section><section class="panel"><div class="panel-head"><div><h2 id="report-secondary-title">Выручка по зонам</h2><span class="muted">Детализация для контроля смены</span></div></div><div class="report-breakdown" id="report-secondary"><div class="empty">—</div></div></section></div>`;
  const drawRows = (data, labels) => { const rows = Object.entries(data || {}); return rows.length ? rows.map(([key, value]) => `<div class="report-row"><span>${esc(labels[key] || key)}</span><strong>${money(value)}</strong></div>`).join('') : '<div class="empty">Данных за выбранную дату нет</div>'; };
  const load = () => { const date = document.querySelector('#report-date').value; const type = document.querySelector('#report-type').value; api(`/api/finance/report?date=${encodeURIComponent(date)}&type=${type}`).then((report) => { document.querySelector('#report-revenue').textContent = money(report.revenue); document.querySelector('#report-checks').textContent = report.checksCount ?? report.closedOrders ?? 0; document.querySelector('#report-meta').textContent = `${report.paymentCount || 0} операций оплаты`; document.querySelector('#report-cash').textContent = money(report.cash); document.querySelector('#report-digital').textContent = money(Number(report.card || 0) + Number(report.qr || 0)); document.querySelector('#report-number').textContent = `${report.reportNumber} · ${new Date(report.generatedAt).toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' })}`; document.querySelector('#report-payments').innerHTML = drawRows(report.byPaymentMethod, { cash: 'Наличные', card: 'Карта', qr: 'QR', 'не указан': 'Не указан' }); document.querySelector('#report-secondary-title').textContent = type === 'waiter' ? 'Выручка по сотрудникам' : 'Выручка по зонам'; document.querySelector('#report-secondary').innerHTML = drawRows(type === 'waiter' ? report.byStaff : report.byStation, { kitchen: 'Кухня', bar: 'Бар', hookah: 'Кальяны', ingredients: 'Ингредиенты', stock: 'Склад', delivery: 'Доставка', other: 'Другое' }); }).catch(() => portalNotice('Не удалось сформировать отчёт', 'error')); };
  document.querySelector('#report-refresh').addEventListener('click', load); document.querySelector('#report-type').addEventListener('change', load); load();
}

function renderIntegrations() {
  const target = document.querySelector('#page-content'); if (!target) return;
  target.innerHTML = `<div class="page-title"><div><p class="eyebrow">ПОДКЛЮЧЕНИЯ</p><h1>Интеграции</h1><p class="muted">Подготовленные точки подключения к государственным, платёжным и коммуникационным сервисам.</p></div><span class="live-dot">● Архитектура готова</span></div><section class="panel wide"><div class="panel-head"><div><h2>Состояние интеграций</h2><span class="muted">Включение выполняется после настройки реквизитов и тестового контура.</span></div></div><div class="integration-grid" id="integration-grid"><div class="empty">Загрузка интеграций…</div></div></section><section class="content-grid"><section class="panel"><div class="panel-head"><h2>Безопасный запуск</h2></div><div class="check-list"><div><span class="check ok">${icon('circle-check')}</span><div><b>Изолированный адаптер</b><small>Каждый внешний сервис подключается отдельным модулем.</small></div></div><div><span class="check ok">${icon('circle-check')}</span><div><b>Журнал обмена</b><small>Ошибки и ответы внешних API сохраняются в audit.</small></div></div><div><span class="check warn">${icon('alert-triangle')}</span><div><b>Тестовый режим</b><small>Продакшен-реквизиты пока не вводятся.</small></div></div></div></section><section class="panel"><div class="panel-head"><h2>Следующий этап</h2></div><p class="muted">Подключение ЕГАИС, Честного знака, ККТ и ОФД выполняется после переноса CRM на российский сервер и получения реквизитов организации.</p></section></div>`;
  const labels = { egais: ['ЕГАИС', 'Алкогольный учёт'], honestMark: ['Честный знак', 'Маркировка товаров'], kkt: ['ККТ', 'Фискальные чеки'], ofd: ['ОФД', 'Передача чеков'], payments: ['Платежи', 'Карта и QR'], telegram: ['Telegram', 'Уведомления и связь'] };
  api('/api/integrations').then((data) => { document.querySelector('#integration-grid').innerHTML = Object.entries(labels).map(([key, value]) => { const item = data[key] || {}; const enabled = Boolean(item.enabled); return `<article class="integration-card"><div class="integration-icon">${icon(enabled ? 'circle-check' : 'alert-triangle')}</div><div><h3>${value[0]}</h3><p>${value[1]}</p><span class="badge ${enabled ? 'success' : 'warning'}">${enabled ? 'Подключено' : 'Запланировано'}</span></div><button class="button small" type="button" disabled>${enabled ? 'Настроено' : 'Подключить позже'}</button></article>`; }).join(''); }).catch(() => { document.querySelector('#integration-grid').innerHTML = '<div class="empty">Не удалось загрузить состояние интеграций</div>'; });
}

function renderNetwork() {
  const target = document.querySelector('#page-content'); if (!target) return;
  target.innerHTML = `<div class="page-title"><div><p class="eyebrow">СЕТЕВОЕ УПРАВЛЕНИЕ</p><h1>Заведения сети</h1><p class="muted">Единый контур для нескольких точек. Выбор текущей точки переключает рабочий контур и фиксируется в аудите.</p></div><span class="live-dot">● Архитектура готова</span></div><div class="content-grid"><section class="panel wide"><div class="panel-head"><div><h2>Точки сети</h2><span class="muted" id="network-count">Загрузка…</span></div></div><div class="network-list" id="network-list"><div class="empty">Загрузка заведений…</div></div></section><section class="panel"><div class="panel-head"><h2>Добавить точку</h2></div><form class="stack-form" id="network-form"><label>Название<input id="network-name" required maxlength="120" placeholder="Территория — центр"></label><label>Город<input id="network-city" required maxlength="80" placeholder="Тюмень"></label><label>Адрес<input id="network-address" required maxlength="240" placeholder="Улица, дом"></label><label>Формат<input id="network-format" maxlength="80" value="кальян-бар"></label><label>Телефон<input id="network-phone" maxlength="32" placeholder="+7 ..."></label><label>Часовой пояс<input id="network-timezone" maxlength="64" value="Asia/Yekaterinburg"></label><button class="button primary" type="submit">Создать точку</button><p class="form-message" id="network-message"></p></form></section></div>`;
  const draw = (items) => { window.__networkItems = items; document.querySelector('#network-count').textContent = `${items.length} ${items.length === 1 ? 'точка' : 'точки'}`; document.querySelector('#network-list').innerHTML = items.length ? items.map((item) => `<article class="network-row"><div><b>${esc(displayName(item.name))}</b><small>${esc(item.format || 'кальян-бар')} · ${esc(item.city)} · ${esc(item.address)}</small><small>${esc(item.phone || 'Телефон не указан')} · ${esc(item.timezone || 'Часовой пояс не указан')}</small></div><div class="toolbar-row"><span class="badge ${item.isCurrent ? 'success' : 'warning'}">${item.isCurrent ? 'Текущая точка' : 'Подготовлена'}</span>${item.isCurrent ? '' : `<button class="button small network-select" type="button" data-venue="${esc(item.id)}">Сделать текущей</button>`}<button class="button small network-edit" type="button" data-venue="${esc(item.id)}">Изменить</button>${item.isCurrent ? '' : `<button class="button small danger-outline network-archive" type="button" data-venue="${esc(item.id)}">Архивировать</button>`}</div></article>`).join('') : '<div class="empty">Точки ещё не добавлены</div>'; };
  const load = () => api('/api/network/venues').then((data) => draw(data.items || [])).catch(() => portalNotice('Не удалось загрузить точки сети', 'error')); load();
  document.querySelector('#network-list').addEventListener('click', (event) => { const button = event.target.closest('[data-venue]'); if (!button) return; const id = button.dataset.venue; if (button.classList.contains('network-select')) { api(`/api/network/venues/${encodeURIComponent(id)}/select`, { method: 'POST' }).then(() => { portalNotice('Точка выбрана как текущая', 'success'); load(); }).catch(() => portalNotice('Не удалось выбрать точку', 'error')); } else if (button.classList.contains('network-archive')) { if (!window.confirm('Архивировать точку?')) return; api(`/api/network/venues/${encodeURIComponent(id)}`, { method: 'DELETE' }).then(() => { portalNotice('Точка архивирована', 'success'); load(); }).catch((error) => portalNotice(error.payload?.error === 'current_venue_cannot_be_archived' ? 'Текущую точку нельзя архивировать' : 'Не удалось архивировать точку', 'error')); } else if (button.classList.contains('network-edit')) { const item = (window.__networkItems || []).find((entry) => entry.id === id); if (!item) return; const name = window.prompt('Название точки', item.name); if (name === null) return; const address = window.prompt('Адрес точки', item.address); if (address === null) return; api(`/api/network/venues/${encodeURIComponent(id)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name, address }) }).then(() => { portalNotice('Точка обновлена', 'success'); load(); }).catch(() => portalNotice('Не удалось обновить точку', 'error')); } });
  document.querySelector('#network-form').addEventListener('submit', (event) => { event.preventDefault(); const message = document.querySelector('#network-message'); api('/api/network/venues', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: document.querySelector('#network-name').value.trim(), city: document.querySelector('#network-city').value.trim(), address: document.querySelector('#network-address').value.trim(), format: document.querySelector('#network-format').value.trim(), phone: document.querySelector('#network-phone').value.trim(), timezone: document.querySelector('#network-timezone').value.trim() }) }).then(() => { message.textContent = 'Точка добавлена'; message.className = 'form-message success-message'; event.target.reset(); document.querySelector('#network-format').value = 'кальян-бар'; document.querySelector('#network-timezone').value = 'Asia/Yekaterinburg'; load(); }).catch((error) => { message.textContent = error.payload?.error === 'venue_name_city_address_required' ? 'Заполните название, город и адрес' : 'Не удалось добавить точку'; message.className = 'form-message error-message'; }); });
}

function renderOrders() {
  const target = document.querySelector('#page-content'); if (!target) return; target.classList.add('orders-view');
  target.innerHTML = `<div class="page-title"><div><p class="eyebrow">ОПЕРАЦИИ СМЕНЫ</p><h1>Заказы</h1><p class="muted">Контроль открытых и закрытых заказов, оплат и депозитов VIP-комнат.</p></div><a class="button primary" href="/">Открыть рабочее место</a></div><div class="kpi-grid compact"><article class="kpi"><span>Всего заказов</span><strong id="orders-count">—</strong><small>За текущий период</small></article><article class="kpi"><span>Открытые</span><strong id="orders-open">—</strong><small>Требуют обслуживания</small></article><article class="kpi"><span>Выручка</span><strong id="orders-revenue">—</strong><small>По закрытым заказам</small></article></div><section class="panel wide"><div class="panel-head"><div><h2>Журнал заказов</h2><span class="muted">Можно найти стол, гостя или номер заказа</span></div><div class="toolbar-row"><input class="table-search" id="orders-search" aria-label="Поиск заказов" placeholder="Поиск"><select id="orders-sort" aria-label="Сортировка"><option value="attention">Сначала требуют внимания</option><option value="newest">Сначала новые</option><option value="amount">По сумме</option></select><select id="orders-status" aria-label="Статус"><option value="">Все статусы</option><option value="open">Открыт</option><option value="in_progress">Готовится</option><option value="ready">Готов</option><option value="closed">Закрыт</option><option value="cancelled">Отменён</option></select></div></div><div class="table-wrap"><table class="orders-table"><thead><tr><th>Заказ</th><th>Стол</th><th>Гость</th><th>Статус</th><th>Сумма</th><th>Создан</th><th></th></tr></thead><tbody id="orders-rows"><tr><td colspan="7" class="empty">Загрузка заказов…</td></tr></tbody></table></div></section>`;
  let items = [];
  const total = (order) => Number(order.finalTotal ?? order.total ?? (order.items || []).reduce((sum, item) => sum + Number(item.unitPrice || item.price || 0) * Number(item.quantity || 0), 0));
  const draw = () => { const query = document.querySelector('#orders-search').value.trim().toLowerCase(); const status = document.querySelector('#orders-status').value; const sort = document.querySelector('#orders-sort')?.value || 'attention'; const filtered = items.filter((order) => (!status || order.status === status) && (!query || `${order.id} ${order.tableId} ${order.guestName || ''}`.toLowerCase().includes(query))); const priority = { open: 0, in_progress: 1, ready: 2, closed: 3, cancelled: 4 }; const sorted = [...filtered].sort((a, b) => sort === 'amount' ? total(b) - total(a) : sort === 'newest' ? new Date(b.createdAt || 0) - new Date(a.createdAt || 0) : (priority[a.status] ?? 9) - (priority[b.status] ?? 9) || new Date(b.createdAt || 0) - new Date(a.createdAt || 0)); const rows = document.querySelector('#orders-rows'); rows.innerHTML = sorted.length ? sorted.map((order) => { const statusLabels = { open: 'Открыт', in_progress: 'Готовится', ready: 'Готов', closed: 'Закрыт', cancelled: 'Отменён' }; return `<tr><td><b>${esc(order.id)}</b></td><td>${esc(order.tableId || '—')}</td><td>${esc(order.guestName || 'Без профиля')}</td><td><span class="badge ${order.status === 'closed' ? 'success' : order.status === 'cancelled' ? 'danger' : 'warning'}">${statusLabels[order.status] || order.status}</span></td><td><strong>${money(total(order))}</strong>${Number(order.minimumOrderTotal || 0) ? `<small class="muted">депозит ${money(order.minimumOrderTotal)}</small>` : ''}</td><td>${order.createdAt ? new Date(order.createdAt).toLocaleString('ru-RU', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : '—'}</td><td><a class="button small" href="/?order=${encodeURIComponent(order.id)}">Открыть</a></td></tr>`; }).join('') : '<tr><td colspan="7" class="empty">По выбранным условиям заказов нет</td></tr>'; document.querySelector('#orders-count').textContent = items.length; document.querySelector('#orders-open').textContent = items.filter((order) => !['closed', 'cancelled'].includes(order.status)).length; document.querySelector('#orders-revenue').textContent = money(items.filter((order) => order.status === 'closed').reduce((sum, order) => sum + total(order), 0)); };
  const load = () => api('/api/orders?scope=all').then((data) => { items = data.items || []; draw(); }).catch(() => { document.querySelector('#orders-rows').innerHTML = '<tr><td colspan="7" class="empty">Не удалось загрузить заказы</td></tr>'; portalNotice('Не удалось загрузить заказы', 'error'); });
  document.querySelector('#orders-search').addEventListener('input', draw); document.querySelector('#orders-status').addEventListener('change', draw); document.querySelector('#orders-sort').addEventListener('change', draw); load();
}

function renderClients() {
  const target = document.querySelector('#page-content'); if (!target) return;
  const hiddenLoyaltyFields = '<form id="loyalty-form" hidden><span id="loyalty-balance"></span><input id="loyalty-delta"><input id="loyalty-reason"><button type="submit">Сохранить</button><span id="loyalty-message"></span></form>';
  target.innerHTML = `<div class="page-title"><div><p class="eyebrow">ГОСТИ</p><h1>Гости</h1><p class="muted">Единая карточка гостя, контакты и предпочтения. Сотрудники могут применять скидки из заказа; администратор и управляющий получают уведомления.</p></div><button type="button" class="button primary" id="new-client">${icon('plus')} Новый гость</button></div><div class="client-insights"><article><span>Всего гостей</span><strong id="clients-total">—</strong><small>В основной базе</small></article><article><span>Постоянные и VIP</span><strong id="clients-loyal">—</strong><small>Гости с повторными визитами</small></article><article><span>Оборот гостей</span><strong id="clients-turnover">—</strong><small>По сохранённым карточкам</small></article></div><div class="content-grid"><section class="panel wide"><div class="panel-head"><div><h2>База гостей</h2><span class="muted" id="clients-count">Загрузка…</span></div><div class="clients-toolbar"><input class="table-search" id="clients-search" aria-label="Поиск гостей" placeholder="Имя, телефон, Telegram или вкус"><select id="clients-status-filter" aria-label="Фильтр по статусу"><option value="">Все статусы</option><option value="new">Новые</option><option value="regular">Постоянные</option><option value="vip">VIP</option><option value="blocked">Не обслуживать</option></select><select id="clients-sort" aria-label="Сортировка гостей"><option value="recent">Сначала новые</option><option value="visits">По визитам</option><option value="turnover">По обороту</option><option value="name">По имени</option></select></div></div><div class="client-grid" id="clients-list"></div></section><section class="panel" id="client-editor"><div class="panel-head"><h2 id="client-editor-title">Новый гость</h2><button class="button small" id="client-cancel" type="button">Очистить</button></div><form class="stack-form" id="client-form"><input type="hidden" id="client-id"><div class="client-avatar-editor"><div class="client-avatar large" id="client-avatar-preview" aria-hidden="true">Г</div><div><label class="avatar-upload button small" for="client-avatar-file">${icon('plus')} Фото гостя<input id="client-avatar-file" type="file" accept="image/png,image/jpeg,image/webp" hidden></label><small class="muted">PNG, JPG или WEBP до 1,5 МБ</small></div></div><label>Статус гостя<select id="client-status"><option value="new">Новый</option><option value="regular">Постоянный</option><option value="vip">VIP</option><option value="blocked">Не обслуживать</option></select></label><label>ФИО<input id="client-name" required maxlength="120" placeholder="Имя и фамилия"></label><label>Телефоны<input id="client-phone" type="tel" inputmode="tel" placeholder="+7 (___) ___-__-__; +7 ..."><small class="muted">Можно указать несколько через точку с запятой</small></label><label>Telegram<input id="client-telegram" placeholder="@username или https://t.me/username"></label><label>Вкусы табака<input id="client-tobacco" placeholder="Darkside, мята, ягоды"></label><label>Чаши и крепость<input id="client-bowls" placeholder="Калауд, средняя крепость"></label><label>Барные предпочтения<input id="client-bar" placeholder="Лимонад, Red Bull"></label><label>Аллергии<textarea id="client-allergies" rows="2" placeholder="Орехи, цитрусы…"></textarea></label><label>Заметки<textarea id="client-notes" rows="3" placeholder="Пожелания гостя"></textarea></label><button class="button primary" type="submit">Сохранить карточку</button><p class="form-message" id="client-message"></p></form><div class="discount-policy"><div class="panel-head"><h3>Скидки</h3><span class="muted">С уведомлением руководства</span></div><p class="muted">Сотрудник может применить процентную скидку из заказа с обязательной причиной. Администратор и управляющий получают уведомление, а действие записывается в аудит.</p></div><div class="client-history" id="client-history"><div class="panel-head"><h3>История</h3></div><div class="empty">Выберите гостя</div></div></section></div>`;
  target.insertAdjacentHTML('beforeend', hiddenLoyaltyFields);
  let clients = [];
  const parseTags = (value) => String(value || '').split(',').map((item) => item.trim()).filter(Boolean).slice(0, 30);
  const formatPhones = (items) => (items || []).map((item) => item.number).join(', ');
  const normalizePhoneDraft = (value) => String(value || '').split(/[;,]/).map((part) => { const raw = part.trim(); if (!raw) return ''; const digits = raw.replace(/\D/g, ''); if (!digits) return ''; if (digits === '7') return '+7 '; if (digits.startsWith('7') && digits.length > 1) return `+7 ${digits.slice(1)}`; if (digits.startsWith('8') && digits.length > 1) return `+7 ${digits.slice(1)}`; return `+7 ${digits}`; }).join('; ');
  const guestStatusLabels = { new: 'Новый', regular: 'Постоянный', vip: 'VIP', blocked: 'Не обслуживать' };
  const guestStatusLabelsClass = { new: 'info', regular: 'success', vip: 'warning', blocked: 'danger' };
  const clientInitials = (name) => String(name || 'Гость').trim().split(/\s+/).slice(0, 2).map((part) => part[0] || '').join('').toLocaleUpperCase('ru-RU');
  let pendingAvatarUrl = null;
  const draw = (query = '') => { const list = document.querySelector('#clients-list'); const q = query.toLowerCase(); const status = document.querySelector('#clients-status-filter')?.value || ''; const sort = document.querySelector('#clients-sort')?.value || 'recent'; const filtered = clients.filter((client) => (!status || (client.guestStatus || 'new') === status) && (!q || `${client.name} ${formatPhones(client.phoneNumbers)} ${client.telegram} ${(client.tobaccoPreferences || []).join(' ')} ${(client.barPreferences || []).join(' ')}`.toLowerCase().includes(q))); const sorted = [...filtered].sort((a,b) => sort === 'visits' ? Number(b.visits || 0) - Number(a.visits || 0) : sort === 'turnover' ? Number(b.totalSpent || 0) - Number(a.totalSpent || 0) : sort === 'name' ? String(a.name || '').localeCompare(String(b.name || ''), 'ru') : new Date(b.createdAt || 0) - new Date(a.createdAt || 0)); document.querySelector('#clients-count').textContent = `${filtered.length} ${pluralRu(filtered.length,'гость','гостя','гостей')} из ${clients.length}`; document.querySelector('#clients-total').textContent = clients.length; document.querySelector('#clients-loyal').textContent = clients.filter((client) => ['regular','vip'].includes(client.guestStatus)).length; document.querySelector('#clients-turnover').textContent = money(clients.reduce((sum, client) => sum + Number(client.totalSpent || 0), 0)); list.innerHTML = sorted.length ? sorted.map((client) => `<article class="client-card" data-client-id="${esc(client.id)}" role="button" tabindex="0" aria-label="Открыть карточку гостя ${esc(client.name)}"><div class="client-card-head"><div class="client-card-person"><span class="client-avatar" aria-hidden="true">${client.avatarUrl ? `<img src="${esc(client.avatarUrl)}" alt="">` : esc(clientInitials(client.name))}</span><div><h3>${esc(client.name)}</h3><small>${esc(formatPhones(client.phoneNumbers) || 'Телефон не указан')}${client.telegram ? ` · ${esc(client.telegram)}` : ''}</small></div></div><div class="client-actions"><span class="badge ${guestStatusLabelsClass[client.guestStatus || 'new'] || 'info'}">${esc(guestStatusLabels[client.guestStatus || 'new'] || guestStatusLabels.new)}</span><button type="button" class="button small client-archive" data-client-action="archive" data-client-id="${esc(client.id)}">Архивировать</button>${portalUser.role === 'owner' ? `<button type="button" class="button small danger-outline client-delete" data-client-action="delete" data-client-id="${esc(client.id)}" aria-label="Удалить гостя">Удалить</button>` : ''}</div></div><div class="client-tags"><span>${Number(client.visits || 0)} ${pluralRu(client.visits || 0,'визит','визита','визитов')}</span><span>Оборот: ${money(client.totalSpent || 0)}</span>${client.allergies ? `<span class="badge warning">Аллергии: ${esc(client.allergies)}</span>` : ''}</div><div class="preference-line"><b>Табак:</b> ${esc((client.tobaccoPreferences || []).join(', ') || 'не указано')}</div><div class="preference-line"><b>Бар:</b> ${esc((client.barPreferences || []).join(', ') || 'не указано')}</div><div class="preference-line"><b>Чаши:</b> ${esc((client.bowlPreferences || []).join(', ') || 'не указано')}</div>${client.notes ? `<p class="muted">${esc(client.notes)}</p>` : ''}</article>`).join('') : '<div class="empty">Гости не найдены</div>'; };
  const fill = (client) => { pendingAvatarUrl = client?.avatarUrl || null; const preview = document.querySelector('#client-avatar-preview'); if (preview) preview.innerHTML = pendingAvatarUrl ? `<img src="${esc(pendingAvatarUrl)}" alt="">` : esc(clientInitials(client?.name || 'Гость')); const avatarInput = document.querySelector('#client-avatar-file'); if (avatarInput) avatarInput.value = ''; document.querySelector('#client-id').value = client?.id || ''; document.querySelectorAll('.client-card').forEach((card) => card.classList.toggle('is-selected', Boolean(client && card.dataset.clientId === client.id))); document.querySelector('#client-editor-title').textContent = client ? `Карточка: ${client.name}` : 'Новый гость'; document.querySelector('#client-status').value = client?.guestStatus || 'new'; document.querySelector('#client-name').value = client?.name || ''; document.querySelector('#client-phone').value = formatPhones(client?.phoneNumbers).replaceAll(', ', '; '); document.querySelector('#client-telegram').value = client?.telegram || ''; document.querySelector('#client-tobacco').value = (client?.tobaccoPreferences || []).join(', '); document.querySelector('#client-bowls').value = (client?.bowlPreferences || []).join(', '); document.querySelector('#client-bar').value = (client?.barPreferences || []).join(', '); document.querySelector('#client-allergies').value = client?.allergies || ''; document.querySelector('#client-notes').value = client?.notes || ''; document.querySelector('#loyalty-balance').textContent = client ? `${Number(client.loyaltyPoints || 0)} ${pluralRu(client.loyaltyPoints || 0,'бонус','бонуса','бонусов')}` : 'Выберите гостя'; const history = document.querySelector('#client-history'); if (!client) { history.innerHTML = '<div class="panel-head"><h3>История</h3></div><div class="empty">Выберите гостя</div>'; } else { history.innerHTML = '<div class="panel-head"><h3>История</h3></div><div class="empty">Загрузка истории…</div>'; api(`/api/clients/${encodeURIComponent(client.id)}/history`).then((data) => { const orders = (data.orders || []).map((order) => `<div class="history-row"><div><b>Заказ ${esc(order.id)}</b><small>${esc(order.tableId || '—')} · ${order.status === 'closed' ? 'Закрыт' : 'Открыт'} · ${order.createdAt ? new Date(order.createdAt).toLocaleDateString('ru-RU') : '—'}</small></div><strong>${money(order.total || 0)}</strong></div>`).join(''); const reservations = (data.reservations || []).map((item) => `<div class="history-row"><div><b>Бронь ${esc(item.tableId || '—')}</b><small>${esc(item.date || '')} ${esc(item.time || '')} · ${item.status === 'confirmed' ? 'Подтверждена' : 'Отменена'}</small></div><strong>${item.deposit ? `Депозит ${money(item.deposit)}` : 'Без депозита'}</strong></div>`).join(''); history.innerHTML = `<div class="panel-head"><h3>История</h3><span class="muted">${(data.orders || []).length} ${pluralRu((data.orders || []).length,'заказ','заказа','заказов')} · ${(data.reservations || []).length} ${pluralRu((data.reservations || []).length,'бронь','брони','броней')}</span></div>${orders || reservations ? `<div class="history-list">${orders}${reservations}</div>` : '<div class="empty">История пока пуста</div>'}`; }).catch(() => { history.innerHTML = '<div class="panel-head"><h3>История</h3></div><div class="empty">Не удалось загрузить историю</div>'; }); } document.querySelector('#client-editor').scrollIntoView({ behavior: 'smooth', block: 'center' }); };
  const load = () => api('/api/clients').then((data) => { clients = data.items || []; draw(document.querySelector('#clients-search').value); }).catch(() => portalNotice('Не удалось загрузить базу гостей', 'error'));
  const phoneInput = document.querySelector('#client-phone'); phoneInput.addEventListener('focus', () => { if (!phoneInput.value.trim()) phoneInput.value = '+7 '; }); phoneInput.addEventListener('input', () => { const caret = phoneInput.selectionStart; const before = phoneInput.value; const normalized = normalizePhoneDraft(before); if (normalized !== before) { phoneInput.value = normalized; phoneInput.setSelectionRange(Math.min(normalized.length, caret + (normalized.length - before.length)), Math.min(normalized.length, caret + (normalized.length - before.length))); } });
  document.querySelector('#client-avatar-file').addEventListener('change', (event) => { const file = event.target.files?.[0]; if (!file) return; if (!['image/png', 'image/jpeg', 'image/webp'].includes(file.type) || file.size > 1500000) { event.target.value = ''; portalNotice('Выберите PNG, JPG или WEBP до 1,5 МБ', 'error'); return; } const reader = new FileReader(); reader.onload = () => { pendingAvatarUrl = String(reader.result || ''); const preview = document.querySelector('#client-avatar-preview'); if (preview) preview.innerHTML = `<img src="${esc(pendingAvatarUrl)}" alt="">`; }; reader.readAsDataURL(file); }); document.querySelector('#clients-search').addEventListener('input', (event) => draw(event.target.value)); document.querySelector('#clients-status-filter').addEventListener('change', () => draw(document.querySelector('#clients-search').value)); document.querySelector('#clients-sort').addEventListener('change', () => draw(document.querySelector('#clients-search').value)); document.querySelector('#new-client').addEventListener('click', () => fill(null)); document.querySelector('#client-cancel').addEventListener('click', () => fill(null)); const activateClientCard = (card) => { if (card) fill(clients.find((client) => client.id === card.dataset.clientId)); }; document.querySelector('#clients-list').addEventListener('click', (event) => { const action = event.target.closest('[data-client-action]'); if (action) { event.stopPropagation(); const id = action.dataset.clientId; const isDelete = action.dataset.clientAction === 'delete'; if (!window.confirm(isDelete ? 'Удалить гостя без возможности восстановления?' : 'Архивировать гостя? Он исчезнет из основной базы, но история сохранится.')) return; action.disabled = true; api(`/api/clients/${encodeURIComponent(id)}${isDelete ? '' : '/archive'}`, { method: isDelete ? 'DELETE' : 'POST', headers: { 'Content-Type': 'application/json' }, body: isDelete ? undefined : '{}' }).then(() => { portalNotice(isDelete ? 'Гость удалён' : 'Гость архивирован', 'success'); load(); fill(null); }).catch((error) => { action.disabled = false; portalNotice(error.payload?.error === 'client_delete_owner_required' ? 'Удалять гостей может только владелец' : 'Не удалось изменить гостя', 'error'); }); return; } activateClientCard(event.target.closest('[data-client-id]')); }); document.querySelector('#clients-list').addEventListener('keydown', (event) => { const card = event.target.closest('[data-client-id]'); if (card && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); activateClientCard(card); } }); document.querySelector('#loyalty-form').addEventListener('submit', (event) => { event.preventDefault(); const id = document.querySelector('#client-id').value; const delta = Number(document.querySelector('#loyalty-delta').value); const reason = document.querySelector('#loyalty-reason').value.trim(); const message = document.querySelector('#loyalty-message'); if (!id) { message.textContent = 'Сначала выберите гостя'; message.className = 'form-message error-message'; return; } api(`/api/clients/${encodeURIComponent(id)}/loyalty`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ delta, reason }) }).then((result) => { message.textContent = `Баланс: ${Number(result.loyaltyPoints || 0)} ${pluralRu(result.loyaltyPoints || 0,'бонус','бонуса','бонусов')}`; message.className = 'form-message success-message'; const client = clients.find((item) => item.id === id); if (client) { client.loyaltyPoints = result.loyaltyPoints; fill(client); draw(document.querySelector('#clients-search').value); } event.target.reset(); }).catch((error) => { message.textContent = error.payload?.error === 'invalid_loyalty_adjustment' ? 'Укажите ненулевую сумму и причину' : 'Не удалось провести операцию'; message.className = 'form-message error-message'; }); });
  document.querySelector('#client-form').addEventListener('submit', (event) => { event.preventDefault(); const id = document.querySelector('#client-id').value; const rawPhones = document.querySelector('#client-phone').value.split(/[;,]/).map((number, index) => ({ label: index ? 'Дополнительный' : 'Основной', number: number.trim(), primary: index === 0 })).filter((item) => item.number); const payload = { name: document.querySelector('#client-name').value.trim(), phoneNumbers: rawPhones, telegram: document.querySelector('#client-telegram').value.trim(), tobaccoPreferences: parseTags(document.querySelector('#client-tobacco').value), bowlPreferences: parseTags(document.querySelector('#client-bowls').value), barPreferences: parseTags(document.querySelector('#client-bar').value), allergies: document.querySelector('#client-allergies').value.trim(), notes: document.querySelector('#client-notes').value.trim(), avatarUrl: pendingAvatarUrl, guestStatus: document.querySelector('#client-status').value }; const message = document.querySelector('#client-message'); api(id ? `/api/clients/${id}` : '/api/clients', { method: id ? 'PATCH' : 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) }).then(() => { message.textContent = 'Карточка сохранена'; message.className = 'form-message success-message'; load(); }).catch((error) => { message.textContent = error.payload?.error === 'invalid_telegram' ? 'Проверьте Telegram-ссылку' : error.payload?.error === 'invalid_phone_numbers' ? 'Введите телефон в формате +7 (___) ___-__-__' : 'Не удалось сохранить карточку'; message.className = 'form-message error-message'; }); }); load();
}

function renderReservations() {
  const target = document.querySelector('#page-content'); if (!target) return;
  target.innerHTML = `<div class="page-title"><div><p class="eyebrow">ГОСТИ И СТОЛЫ</p><h1>Бронирования</h1><p class="muted">Единый календарь броней и депозитов.</p></div><button type="button" class="button primary" id="focus-reservation">${icon('plus')} Новая бронь</button></div><div class="content-grid"><section class="panel"><div class="panel-head"><h2>Новая бронь</h2></div><form id="reservation-form" class="stack-form"><label>Гость<input id="reservation-guest" required placeholder="Имя гостя"></label><label>Телефон<input id="reservation-phone" placeholder="+7 ..."></label><div class="form-row"><label>Дата<input id="reservation-date" type="date" required value="${localDateKey()}"></label><label>Время<input id="reservation-time" type="time" required value="21:00"></label></div><div class="form-row"><label>Стол / комната<select id="reservation-table" required></select></label><label>Гости<input id="reservation-guests" type="number" min="1" value="2" required></label></div><label>Депозит<input id="reservation-deposit" type="number" min="0" step="100" value="0"><small id="reservation-deposit-hint" class="muted">Для VIP-комнаты нужен обязательный депозит.</small></label><label>Комментарий<textarea id="reservation-notes" maxlength="2000" rows="3" placeholder="Пожелания гостя или особые условия"></textarea></label><button type="submit" class="button primary">Подтвердить бронь</button><p class="form-message" id="reservation-message"></p></form></section><section class="panel wide reservation-panel"><div class="panel-head"><h2>Ближайшие бронирования</h2><input class="table-search" id="reservation-filter" aria-label="Поиск бронирования" placeholder="Поиск по гостю"><input class="date-input" id="reservation-list-date" type="date" aria-label="Дата списка" value="${localDateKey()}"></div><div class="reservation-list" id="reservation-list"></div></section></div>`;
  const loadTables = () => api('/api/floor').then((data) => { const tables = data.zones.flatMap((zone) => zone.tables); const select = document.querySelector('#reservation-table'); const deposit = document.querySelector('#reservation-deposit'); const hint = document.querySelector('#reservation-deposit-hint'); select.innerHTML = tables.map((table) => `<option value="${table.id}" data-minimum="${Number(table.minimumOrderTotal || 0)}" ${table.status === 'blocked' ? 'disabled' : ''}>${esc(table.name)}${table.minimumOrderTotal ? ` — депозит ${money(table.minimumOrderTotal)}` : ''}${table.status === 'blocked' ? ' — закрыт' : ''}</option>`).join(''); if (!tables.length) { select.innerHTML = '<option value="">Нет доступных столов</option>'; select.disabled = true; return; } const updateDepositRule = () => { const minimum = Number(select.selectedOptions[0]?.dataset.minimum || 0); deposit.min = String(minimum); if (minimum && Number(deposit.value || 0) < minimum) deposit.value = minimum; hint.textContent = minimum ? `Обязательный депозит: ${money(minimum)}. Он засчитывается в итоговый заказ.` : 'Для обычного стола депозит не требуется.'; }; if (select.dataset.ruleBound !== '1') { select.addEventListener('change', updateDepositRule); select.dataset.ruleBound = '1'; } updateDepositRule(); }).catch(() => { const select = document.querySelector('#reservation-table'); if (select) { select.innerHTML = '<option value="">Не удалось загрузить столы</option>'; select.disabled = true; } portalNotice('Не удалось загрузить столы', 'error'); });
  let reservations = [];
  const draw = (query = '') => { const selectedDate = document.querySelector('#reservation-list-date')?.value || ''; const list = document.querySelector('#reservation-list'); const filtered = reservations.filter((item) => (!selectedDate || item.date === selectedDate) && `${item.guestName} ${item.tableName} ${item.phone}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => `${a.date} ${a.time}`.localeCompare(`${b.date} ${b.time}`)); list.innerHTML = filtered.length ? filtered.map((item) => `<div class="reservation-row"><div><b>${esc(item.guestName)}</b><small>${esc(item.date)} · ${esc(item.time)} · ${esc(item.tableName || item.tableId)} · ${item.guests} ${pluralRu(item.guests,'гость','гостя','гостей')}</small></div><div><strong>${item.deposit ? `Депозит ${money(item.deposit)}` : 'Без депозита'}</strong><span class="badge ${item.status === 'confirmed' ? 'success' : 'danger'}">${item.status === 'confirmed' ? 'Подтверждена' : 'Отменена'}</span>${item.status === 'confirmed' ? `<button type="button" class="button small danger-outline reservation-cancel" data-reservation="${item.id}">Отменить</button>` : ''}</div></div>`).join('') : '<div class="empty">Бронирований пока нет</div>'; };
  const load = () => api('/api/reservations').then((data) => { reservations = data.items || []; draw(document.querySelector('#reservation-filter').value); }).catch(() => { reservations = []; draw(document.querySelector('#reservation-filter').value); portalNotice('Не удалось загрузить бронирования', 'error'); });
  document.querySelector('#reservation-filter').addEventListener('input', (event) => draw(event.target.value)); document.querySelector('#reservation-list-date')?.addEventListener('input', () => draw(document.querySelector('#reservation-filter').value));
  document.querySelector('#reservation-list')?.addEventListener('click', (event) => { const button = event.target.closest('[data-reservation]'); if (!button || button.disabled || !window.confirm('Отменить бронирование?')) return; button.disabled = true; api(`/api/reservations/${button.dataset.reservation}/cancel`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' }).then(() => { portalNotice('Бронирование отменено', 'success'); load(); }).catch(() => { button.disabled = false; portalNotice('Не удалось отменить бронирование', 'error'); }); });
  document.querySelector('#focus-reservation')?.addEventListener('click', () => { document.querySelector('#reservation-form')?.scrollIntoView({ behavior: 'smooth', block: 'center' }); document.querySelector('#reservation-guest')?.focus(); });
  document.querySelector('#reservation-form').addEventListener('submit', (event) => { event.preventDefault(); const form = event.target; if (form.dataset.submitting === '1') return; form.dataset.submitting = '1'; const submit = form.querySelector('button[type="submit"]'); if (submit) submit.disabled = true; const message = document.querySelector('#reservation-message'); const value = { guestName: document.querySelector('#reservation-guest').value.trim(), phone: document.querySelector('#reservation-phone').value.trim(), date: document.querySelector('#reservation-date').value, time: document.querySelector('#reservation-time').value, tableId: document.querySelector('#reservation-table').value, guests: Number(document.querySelector('#reservation-guests').value), deposit: Number(document.querySelector('#reservation-deposit').value), notes: document.querySelector('#reservation-notes').value.trim() }; api('/api/reservations', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(value) }).then(() => { message.textContent = 'Бронь подтверждена'; message.className = 'form-message success-message'; event.target.reset(); document.querySelector('#reservation-date').value = localDateKey(); document.querySelector('#reservation-time').value = '21:00'; loadTables(); load(); api('/api/floor').catch(() => {}); }).catch((error) => { const reason = String(error.payload?.error || error.message || ''); message.className = 'form-message error-message'; message.textContent = reason === 'table_already_reserved' ? 'Этот стол уже занят на выбранное время' : reason.startsWith('vip_deposit_below_minimum') || reason === 'vip_deposit_below_minimum' ? `Для этой VIP-комнаты нужен депозит от ${money(error.payload?.requiredDeposit || Number(reason.split(':')[1] || 0))}` : reason === 'invalid_guest_phone' ? 'Проверьте телефон гостя' : reason === 'invalid_guest_count' ? 'Количество гостей должно быть от 1 до 50' : reason === 'invalid_reservation_datetime' ? 'Проверьте дату и время бронирования' : reason === 'guest_name_too_long' ? 'Имя гостя должно быть до 120 символов' : reason === 'reservation_notes_too_long' ? 'Комментарий должен быть до 2000 символов' : reason === 'table_unavailable' ? 'Этот стол закрыт для бронирований' : 'Не удалось создать бронь'; }).finally(() => { form.dataset.submitting = '0'; if (submit) submit.disabled = false; }); });
  loadTables(); load();
}

